def single_number(nums):
    result = 0
    for num in nums:
        result ^= num  # duplicates cancel out
    return result

def count_set_bits(n):
    count = 0
    while n:
        n &= (n - 1)  # clears the lowest set bit
        count += 1
    return count

def dp_1d(n):
    if n == 0:
        return base_case_0
    dp = [0] * (n + 1)
    dp[0] = base_case_0
    dp[1] = base_case_1
    for i in range(2, n + 1):
        dp[i] = combine(dp[i - 1], dp[i - 2])  # the recurrence
    return dp[n]

# Space-optimized version (only need the last two states)
def dp_1d_optimized(n):
    prev2, prev1 = base_case_0, base_case_1
    for i in range(2, n + 1):
        prev2, prev1 = prev1, combine(prev1, prev2)
    return prev1

def dp_2d(s1, s2):
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[n][m]

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def fast_pow(base, exp, mod=None):
    result = 1
    while exp > 0:
        if exp & 1:
            result *= base
            if mod:
                result %= mod
        base *= base
        if mod:
            base %= mod
        exp >>= 1
    return result

class DLLNode:
    def __init__(self, key=0, val=0):
        self.key, self.val = key, val
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.map = {}  # key -> DLLNode, for O(1) lookup
        self.head = DLLNode()  # most recently used sits next to head
        self.tail = DLLNode()  # least recently used sits next to tail
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _insert_front(self, node):
        node.next, node.prev = self.head.next, self.head
        self.head.next.prev = node
        self.head.next = node

    def get(self, key):
        if key not in self.map:
            return -1
        node = self.map[key]
        self._remove(node)
        self._insert_front(node)
        return node.val

    def put(self, key, val):
        if key in self.map:
            self._remove(self.map[key])
        node = DLLNode(key, val)
        self.map[key] = node
        self._insert_front(node)
        if len(self.map) > self.cap:
            lru = self.tail.prev
            self._remove(lru)
            del self.map[lru.key]
